const initial=()=>({filter:'全部项目',scroll:0,current:'application',tab:'changes',layoutVersion:4,outcome:'success',files:[{id:'procedure',name:'采购控制程序',type:'Markdown',rev:3,latest:3,status:'review',drafts:{},notes:[],updates:{}},{id:'evaluation',name:'供应商评价记录',type:'Markdown 表单',rev:3,latest:3,status:'review',drafts:{},notes:[],updates:{}},{id:'application',name:'采购申请单',type:'Markdown 表单',rev:2,latest:2,status:'review',drafts:{},notes:[],updates:{}}]});
