 procedure:[{title:'§7 · 供应商评价记录 / 记录编号',find:'| 8 | 供应商评价记录',value:'QR-GL-7.4.01-02',before:'未注明编号',table:true},{title:'§7 · 记录编号更新说明',find:'**注**：旧编号',value:'新记录表定稿后，同步修订 GL-7.4-01、PD-7.4、质量手册正文引用。',before:''}],
 evaluation:[{title:'基本信息 · 供应商类别 / 类别选项',find:'| 供应商类别 |',value:'□Ⅰ类（关键） □Ⅱ类 □Ⅲ类 □Ⅳ类',before:'□Ⅰ类 □Ⅱ类 □Ⅲ类',table:true},{title:'编制说明 · 第 5 条整改跟踪',find:'5. **整改跟踪**',value:'须关联QR-PD-8.5.2对应编号跟踪整改闭环',before:'跟踪整改'}],
 application:[{title:'表单正文 · 计划周期 / 周期选项',find:'| 计划周期 |',value:'□月度 □季度 □年度 □临时',before:'□月度 □季度 □年度',table:true},{title:'编制说明 · 第 5 条供方选择',find:'5. **供方选择**',value:'（QR-GL-7.4.01-01）',before:''}]
