function changesFor(x){if(x.id==='application')return fillChanges(x);return x.rev>(x.id==='application'?2:3)?[{title:'本轮补充核对说明',note:window.procurementFixtures[x.id].next}]:changeExamples[x.id]}
function differenceText(line,c,changed){const inline=t=>esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');if(!changed)return inline(line);const pos=line.indexOf(c.value);return pos<0?inline(line):inline(line.slice(0,pos))+(c.before?`<del aria-label="删除内容">${esc(c.before)}</del>`:'')+`<ins aria-label="新增内容">${esc(c.value)}</ins>`+inline(line.slice(pos+c.value.length))}
function contextChange(x,c,n){const lines=window.procurementFixtures[x.id].content.split('\n');let body;if(c.note){body=`<p class="context-line"><ins>${esc(c.note)}</ins></p><p class="small muted">附在候选正文末尾的演示核对说明；模板正文未改。</p>`}else{const k=lines.findIndex(l=>l.includes(c.find));if(k<0)return '<p>无法定位此演示变化，请检查源模板。</p>';if(c.table){let a=k,b=k;while(a>0&&lines[a-1].trim().startsWith('|'))a--;while(b+1<lines.length&&lines[b+1].trim().startsWith('|'))b++;body=`<div class="tablewrap context-table" role="region" tabindex="0" aria-label="${esc(c.title)}"><table>`+lines.slice(a,b+1).filter(l=>!/^\|[\s:|-]+\|$/.test(l.trim())).map((l,i)=>`<tr class="${l===lines[k]?'changed-row':''}">`+l.trim().replace(/^\||\|$/g,'').split('|').map(cell=>`<${i?'td':'th'}>${differenceText(cell.trim(),c,l===lines[k]&&cell.includes(c.value))}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>'}else body=lines.slice(Math.max(0,k-1),Math.min(lines.length,k+2)).filter(l=>l.trim()).map(l=>`<p class="context-line">${differenceText(l,c,l===lines[k])}</p>`).join('')}return `<section class="change-block ${(x.changePositions?.[x.rev]||0)===n?'is-active':''}" id="change-${n}" tabindex="-1"><div class="change-heading"><h3>${n+1}. ${esc(c.title)}</h3><button data-quote="${esc(c.title)} · 变化 ${n+1}">对此变化提意见</button></div>${body}</section>`}
function contextualChanges(x){const items=changesFor(x),current=Math.min(x.changePositions?.[x.rev]||0,items.length-1);return `<div class="change-toolbar"><strong>候选 ${x.rev-1} → ${x.rev}</strong><div class="row"><button data-change-step="-1" ${current===0?'disabled':''} aria-label="上一处变化">↑ 上一处</button><span role="status">变化 ${current+1} / ${items.length}</span><button data-change-step="1" ${current===items.length-1?'disabled':''} aria-label="下一处变化">下一处 ↓</button></div></div><div class="change-legend"><del>删除内容</del><ins>新增内容</ins><span>未高亮部分为原文上下文</span></div><p class="small muted">当前内容依据真实模板；修改前为合成遗漏样例，不代表模板历史版本。表格空白未填造记录。</p>${contextChange(x,items[current],current)}<details class="evidence"><summary>查看变化的依据</summary><p>${esc(window.procurementFixtures[x.id].sourceName)}；变化位置见各段标题。原始模板可在“资料与依据”下载。</p></details>`}
function moveChange(step){state.reviewPane='document';const x=f(),items=changesFor(x);x.changePositions=x.changePositions||{};x.changePositions[x.rev]=Math.max(0,Math.min(items.length-1,(x.changePositions[x.rev]||0)+step));render();const target=document.getElementById(`change-${x.changePositions[x.rev]}`);target.focus({preventScroll:true});target.scrollIntoView({block:'start'});save()}
function detailBody(x){if(x.id==='application')return fillBody(x);
 const d=window.procurementFixtures[x.id],returned=x.rev>(x.id==='application'?2:3),update=x.updates[x.rev];
 if(state.tab==='context')return `<h3>摘要与关联</h3>${summaryDisclosure(x)}${inspectionContext(x)}`;
 if(state.tab==='sources')return `<h3>真实模板来源</h3><p>${esc(d.sourceName)}<br>模板版次 ${d.version} · ${d.kind}</p><p>引用位置：${d.position}<br>${d.basis}</p><p><a href="${d.sourceUrl}" download>下载原始 Markdown 模板</a></p><details><summary>模板快照校验信息</summary><p style="overflow-wrap:anywhere">SHA-256：${d.sourceHash}</p></details><p class="small muted">公司代号 QH-DEMO、青禾制造、候选轮次和变化前文本为合成演示。模板原文来自本地模板库；它不是客户事实或法规已核验的证明。原始模板保留维护历史，候选正文不继承模板作者的修订活动。</p>`;
 if(state.tab==='full')return `<h3>${d.name} · 候选内容（演示）</h3><p class="small muted">依据模板 ${d.version} 展示；[日期]及签批空白保持待填写。MVP 使用 Markdown 填写和交付；此处为候选内容演示，Excel 转换后置。原始模板可在“资料与依据”下载核对。</p>${templateHtml(d.content)}${returned?`<div class="notice"><strong>本轮补充核对说明（演示，不属于模板原文）</strong><p>${esc(d.next)}</p></div>`:''}`;
 if(state.tab==='changes')return contextualChanges(x);
 return `${update?`<h3>上次意见的处理情况</h3><div class="resultrow"><strong>你的意见</strong><p>${esc(update)}</p></div><div class="resultrow"><span class="tag">固定演示结果 · 待核对</span><p>${d.next}</p><p class="small muted">原型不分析自由输入；此说明仅演示新一轮结果的展示。</p><button data-tab="changes">查看对应变化</button></div>`:`<div class="eyebrow">真实模板适配 / 合成客户场景</div><h3>${d.summary}</h3><ul><li>${d.after}</li><li>${d.basis}</li></ul>`}<div class="resultrow"><strong>保留的模板内容</strong><p>${x.id==='procedure'?'生产采购由生产主管审核、总经理批准；研发采购由研发负责人审核、总经理批准。':x.id==='evaluation'?'保留初评、年度再评价、定期综合评价三种类型；质量、技术、交付、服务、价格五个评价栏目以及原有签批栏。':'保留计划周期、库存确认、研发样品补充信息，以及申请人、部门负责人审核、总经理批准栏。'}</p><p>未填写客户业务记录、日期或签字。${returned?'本轮其他模板正文未变，仅附加核对说明。':''}</p></div><div class="row"><span class="tag">${d.kind}</span><span class="tag">模板 ${d.version}</span><span class="tag ${needsScope(x)?'amber':'green'}">${needsScope(x)?'适用性待确认 · 暂不能批准':'演示质量结果 · 非真实校验'}</span></div><details class="evidence"><summary>查看检查边界</summary><p>${needsScope(x)?'当前版本有适用性问题，批准暂被阻止。':'当前质量状态用于演示批准交互。'}没有运行业务质量校验。内部批准不替代客户企业的签批。完整模板及编制说明请在内容和来源页核对。</p></details>`;
}
// Draft persistence and execution are simulated; production requires server APIs.
const earlierDraft=x=>Object.entries(x.drafts).filter(([rev,text])=>Number(rev)<x.rev&&text.trim()&&x.carriedDrafts?.[rev]!==text).sort((a,b)=>Number(b[0])-Number(a[0])).map(([rev,text])=>({rev:Number(rev),text}))[0];
function feedbackPanel(x,draft){const busy=['submitted','running'].includes(x.status),previous=earlierDraft(x);return `<section class="feedback"><label for="feedback">${busy?'下轮补充与修改草稿':'本文件补充与修改意见'}</label><small>${busy?'本轮继续执行；新版本返回并核对后，再提交下轮意见。':'只修改当前文件；涉及其他文件时，先确认范围。'}</small>${x.submitted?`<details class="submitted-feedback"><summary>查看最近提交的意见 · 第 ${x.submitted.rev} 版</summary><p>${esc(x.submitted.text)}</p></details>`:''}${previous?`<div class="draft-note"><span>第 ${previous.rev} 版仍有未提交草稿</span><button data-action="reviewDraft">核对并沿用</button></div>`:''}<div class="context">针对：${x.name} · 第 ${x.rev} 版</div><textarea id="feedback" placeholder="${busy?'先记下补充想法，本轮执行不会读取这里的草稿…':'说明需要调整的内容，也可以引用具体位置…'}">${esc(draft)}</textarea><p id="draftSaveState" class="small muted" role="status">${draft?'已保存个人草稿（模拟）':'个人草稿 · 仅本人可见（模拟）'}</p><div class="footactions"><button data-action="submit" ${!draft.trim()||x.status!=='review'||x.rev!==x.latest?'disabled':''}>${busy?'本轮修改中 · 草稿未提交':'提交并修改'}</button><button class="primary desktopapprove" data-action="approve" ${x.status!=='review'||needsScope(x)||x.rev!==x.latest?'disabled':''}>${needsScope(x)?'待补充必要信息':'检查完成并批准此版本'}</button></div><p class="mobilehint">手机支持查看与反馈；正式批准请在桌面完成。</p><p class="small muted draft-prototype-note">当前原型仅在本标签页保存，未接服务器；正式 MVP 支持个人草稿跨设备恢复。</p></section>`}
function work(){const x=f();const latest=x.latest>x.rev;const draft=x.drafts[x.rev]||'';return `<section class="workhead"><div class="crumb"><a href="#board">← 返回工作台</a><span class="muted"> / 青禾制造 / 体系建设</span></div><div class="row between"><div><h1>采购管理成果检查</h1><p>本轮 3 份成果 · 已批准 ${state.files.filter(t=>t.status==='approved').length} 份 · 待检查 ${pending().length} 份</p></div><span class="tag">按文件检查与提交</span></div></section><div class="workbody"><aside class="files" aria-label="本轮成果"><h2>本轮成果</h2>${state.files.map(t=>`<button class="file ${t.id===x.id?'active':''}" data-file="${t.id}" aria-current="${t.id===x.id?'true':'false'}"><span class="small muted">${t.type}</span><strong>${t.name}</strong>${tag(t)}<small>查看第 ${t.rev} 版${t.latest>t.rev?` · 有第 ${t.latest} 版更新`:''}${t.drafts[t.rev]?' · 有未提交意见':''}</small></button>`).join('')}<details><summary>工作范围与输入</summary><p>依据 3 份真实 Markdown 模板，采购申请单演示数据填写与补充；其余文件仍演示模板适配。客户数据为合成样例，签字留空。</p></details></aside><section class="content"><div class="filetitle row between"><div><h2>${x.name}</h2><p class="small muted">${x.id==='application'?'填写中的记录草稿（合成）':window.procurementFixtures[x.id].kind} · QH-DEMO-${window.procurementFixtures[x.id].code} · 模板 ${window.procurementFixtures[x.id].version} · 候选 ${x.rev}（演示）</p></div>${tag(x)}</div>${scopeAlert(x)}${latest?`<div class="notice"><strong>有新版本：第 ${x.latest} 版</strong><p>你仍在查看第 ${x.rev} 版，未提交意见已保留。不会自动替换正文或转移意见。</p><div class="row"><button data-action="switch">切换到第 ${x.latest} 版</button><span>旧版本意见保留，可随时返回。</span></div></div>`:''}${x.status==='submitted'?`<div class="notice success"><strong>本文件意见已提交</strong><p>当前停留在本文件。服务器执行尚未发生，本原型可在下方演示后续状态。</p></div>`:''}${x.status==='running'?'<div class="notice"><strong>修改中 · 演示</strong><p>正在模拟处理已提交要求；下轮草稿不会并入本轮。</p></div>':''}${x.status==='unknown'?'<div class="notice"><strong>批准结果待核实</strong><p>尚不能确认操作是否成功，保持当前文件；不要重复提交批准。</p><button data-action="reconcile">演示核实结果</button></div>':''}${x.status==='approved'?`<div class="notice success">第 ${x.approvedRev} 版已批准（演示），尚未发布或交付。</div>`:''}${!pending().length?`<div class="notice ${state.files.every(t=>t.status==='approved')?'success':''}">${state.files.every(t=>t.status==='approved')?'本轮文件已全部检查并批准。尚未执行发布或交付。':'本轮暂无待检查文件，仍有修改或结果核实事项。'} <a href="#board">返回工作台 →</a></div>`:''}<div class="tabs" role="tablist" aria-label="成果查看方式">${[['changes','变化详情'],['full',x.type==='Markdown'?'完整内容':'表单内容'],['sources','资料与依据'],['context','摘要与关联']].map(([id,name])=>`<button role="tab" tabindex="${state.tab===id?0:-1}" aria-selected="${state.tab===id}" data-tab="${id}" class="${state.tab===id?'active':''}">${name}</button>`).join('')}</div><article class="paper">${detailBody(x)}</article>${feedbackPanel(x,draft)}<details class="history"><summary>工作记录 · ${x.notes.length} 条</summary><ul>${x.notes.map(n=>`<li>${esc(n)}</li>`).join('')||'<li>本轮候选成果已交回，等待检查。</li>'}</ul></details><div class="democtrl"><div class="row"><span>演示状态：</span><button data-action="incoming">检查中收到新版本</button>${x.status==='submitted'?`${x.id==='procedure'?'<button data-action="impact">发现关联修改</button>':''}<button data-action="start">演示开始修改</button>`:''}${x.status==='running'?`${x.id==='procedure'?'<button data-action="impact">发现关联修改</button>':''}<button data-action="returned">演示修改完成</button>`:''}${x.latest>(x.id==='application'?2:3)?`<select id="viewVersion" aria-label="查看历史版本及草稿">${Array.from({length:x.latest-(x.id==='application'?2:3)+1},(_,i)=>i+(x.id==='application'?2:3)).map(v=>`<option value="${v}" ${v===x.rev?'selected':''}>第 ${v} 版${x.drafts[v]?' · 有草稿':''}</option>`).join('')}</select>`:''}<select id="outcome" aria-label="演示批准返回结果">${[['success','批准成功'],['failure','批准失败'],['unknown','批准结果未知']].map(([v,l])=>`<option value="${v}" ${state.outcome===v?'selected':''}>${l}</option>`).join('')}</select></div></div></section></div>`}
// Reuse the same controls and draft field inside a bounded review workspace.
function changeNavigator(x){const items=changesFor(x),current=Math.min(x.changePositions?.[x.rev]||0,items.length-1);return `<nav class="change-navigator" aria-label="本文件核对位置"><div class="change-nav-title"><strong>本文件共 <b>${items.length}</b> 处需核对</strong><button data-action="changeDirectory" aria-haspopup="dialog">查看全部位置 ▤</button></div><div class="change-current"><span><small>当前 ${current+1} / ${items.length}</small><strong>${esc(items[current].title)}</strong></span><div class="row"><button data-change-step="-1" ${current===0?'disabled':''} aria-label="上一处核对位置">↑ 上一处</button><button data-change-step="1" ${current===items.length-1?'disabled':''} aria-label="下一处核对位置">下一处 ↓</button></div></div></nav>`}
function changeDirectory(){const x=f(),items=changesFor(x),current=Math.min(x.changePositions?.[x.rev]||0,items.length-1);modal(`全部核对位置 · ${items.length} 处`,`<p class="small muted">${esc(x.name)} · 候选 ${x.rev} · 点击跳转，不代表检查完成。</p><label class="directory-search">查找位置<input id="changeSearch" type="search" placeholder="输入章节、字段或关键词" autocomplete="off"></label><div class="change-directory">${items.map((c,i)=>{const missing=x.id==='application'&&fillMissing(x).length>0&&c.fields?.includes('数量');return `<button data-change-index="${i}" data-search="${esc(c.title)}" aria-current="${i===current?'step':'false'}"><span class="change-number">${i+1}</span><span class="change-nav-label">${esc(c.title)}</span>${missing?`<span class="change-pending">缺 ${fillMissing(x).length} 项</span>`:i===current?'<small>当前</small>':''}</button>`}).join('')}</div><p id="directoryResult" role="status" class="small muted">共 ${items.length} 处</p>`,'');$('#changeSearch').focus()}
function focusLayout(){const body=$('.workbody'),content=$('.content'),aside=document.createElement('aside');aside.className='review-aside';aside.setAttribute('aria-label','当前文件意见与处理');const feedback=content.querySelector('.feedback');for(const node of [...content.children])if(node.matches('.notice,.scope-alert'))aside.append(node);aside.append(feedback);const history=content.querySelector('.history');if(history)aside.append(history);const controls=content.querySelector('.democtrl');if(controls){const details=document.createElement('details');details.className='demo-tools';details.innerHTML='<summary>演示状态与版本</summary>';details.append(controls);aside.append(details)}body.append(aside);const switcher=document.createElement('div');switcher.className='pane-switch';switcher.innerHTML=`<button data-review-pane="document" aria-pressed="${state.reviewPane!=='feedback'}">查看文档</button><button data-review-pane="feedback" aria-pressed="${state.reviewPane==='feedback'}">意见与处理${needsScope(f())?` · ${fillMissing(f()).length} 项待补充`:''}</button>`;$('.workhead').append(switcher);body.classList.toggle('pane-feedback',state.reviewPane==='feedback');const paper=$('.paper');if(state.tab==='changes'){paper.insertAdjacentHTML('beforebegin',changeNavigator(f()));paper.querySelector('.change-toolbar .row')?.remove()}paper.setAttribute('tabindex','0');paper.setAttribute('aria-label','文档阅读区域');if(state.tab==='context')paper.querySelectorAll('details').forEach(d=>d.open=true)}
function render(){const startup=window.startupReviewRoute?.()??null;const execution=window.multiChangesRoute?.()??executionRoute();const initialAnalysis=window.projectStartRoute?.()??initialAnalysisRoute();const intake=startup??execution??initialAnalysis??analysisRoute()??projectDeliveryRoute()??deliveryRoute()??supplementRoute()??intakeRoute();const reviewing=location.hash==='#work';document.title=startup!==null?'智举 · 启动信息与文件范围核对':location.hash==='#new-project'?'智举 · 新建项目':initialAnalysis!==null?'智举 · 客户资料提交与分析':execution!==null?(['#execution-review','#changes-preview','#submission-preview'].includes(location.hash)?'智举 · 文件检查':'智举 · 本轮文件进度'):location.hash==='#analysis-supplement'?'智举 · 分析报告与资料缺口':location.hash==='#analysis'?'智举 · 分析报告与资料缺口':reviewing?'智举 · 采购成果检查':location.hash==='#project-delivery'?'智举 · 项目交付':location.hash==='#delivery'?'智举 · 分批交付':location.hash==='#supplement'?'智举 · 补充设备资料':intake!==null?'智举 · 资料与工作范围':'智举 · 工作台';$('#app').innerHTML=intake!==null?intake:reviewing?work():board();window.externalRevisionUpdate?.();window.receiptDemoRefresh?.();document.body.classList.toggle('work-mode',reviewing);document.body.classList.toggle('execution-mode',execution!==null);document.body.classList.toggle('initial-analysis-mode',initialAnalysis!==null);document.body.classList.toggle('analysis-mode',['#analysis','#analysis-supplement'].includes(location.hash));document.querySelector('.demo').textContent=startup!==null?'交互原型 · 固定匿名启动信息与回执；未创建企业事实、正式启动项目或调用 Runner。':(location.hash==='#new-project'||location.hash.startsWith('#project-intake/'))?'交互原型 · 项目与 ZIP 为合成演示；未创建正式业务项目、上传文件或调用 Runner。':location.hash==='#submission-preview'?'交互原型 · 提交与回执为合成演示，未连接业务服务或 Runner；草稿仅在当前浏览器标签页保留。':location.hash==='#project-delivery'?'交互原型 · 项目文件、获批版本与交付资格均为合成演示；未连接业务服务、真实发布或受控导出。':initialAnalysis!==null?'交互原型 · ZIP 与进展使用合成示例；本地文件只记录文件名，未上传、解包或调用 Agent Runner。':execution!==null?'交互原型 · 本轮进度、候选内容与批准为合成演示，未连接客户原件、业务服务或 Agent Runner。':['#analysis','#analysis-supplement'].includes(location.hash)?'交互原型 · 本页使用匿名合成的分析报告示例，未连接客户原件、业务服务或 Agent Runner。':prototypeNotice;document.body.classList.toggle('intake-mode',intake!==null&&execution===null&&initialAnalysis===null);if(reviewing)focusLayout();else if(intake===null){intakeBoardExtras();deliveryBoardExtras()}save();intakeSave();window.startupReviewAfterRender?.()}
function modal(title,body,buttons){$('#dialog').innerHTML=`<h2 id="dialogTitle">${title}</h2>${body}<div class="row"><button data-action="close">返回</button>${buttons}</div>`;$('#dialog').showModal()}
let approvalTarget=null;
function approve(){const x=f();if(needsScope(x)){toast('请先补齐当前候选的缺失信息');return}if(window.innerWidth<=700){toast('请在桌面检查并批准');return}if(x.latest!==x.rev){toast('演示：当前版本已被新候选替代，请切换并重新检查');return}if(x.drafts[x.rev]?.trim()){toast('还有未提交的修改意见，请先处理意见再批准');$('#feedback').focus();return}if(x.status!=='review')return;approvalTarget={id:x.id,rev:x.rev};modal('批准此版本',`<p><strong>${x.name} · 第 ${x.rev} 版</strong><br>青禾制造 / 体系建设 / 采购管理</p><p>演示检查结果：结构、修改范围及版本检查通过，无阻断问题。</p><p>你的确认仅表示智举内部同意此交付版本，不替代模板中的客户总经理或企业负责人签批。批准不代表发布或交付。</p><p class="small muted">批准成功后自动进入下一份待检查文件。</p>`,`<button class="primary" data-action="confirmApprove">确认批准第 ${x.rev} 版</button>`)}
function advance(x){state.reviewPane='document';x.status='approved';x.approvedRev=x.rev;x.notes.push(`第 ${x.rev} 版批准成功（演示）。`);const others=state.files.filter(t=>t.status==='review'&&t.id!==x.id);if(others.length){state.current=others[0].id;state.tab='changes'}render();window.scrollTo(0,0);toast(`${x.name}批准成功${others.length?'，已进入下一份':'，本轮暂无待检查文件'}`)}
function action(a){const x=f();if(fillAction(a,x))return;if(a==='close'){$('#dialog').close();return}if(a==='reset'){state=initial();intakeResetDemo();supplementResetDemo();deliveryResetDemo();projectDeliveryReset();analysisResetDemo();executionDemoReset();initialAnalysisReset();save();render();window.scrollTo(0,0);toast('演示数据已重置');return}if(a==='scopeDemo'){x.scopeConfirmed=x.scopeConfirmed||{};x.scopeConfirmed[x.rev]=true;x.notes.push(`第 ${x.rev} 轮候选适用范围已确认（演示）：保留生产与研发两种用途。`);render();toast('仅模拟当前版本的范围确认，未清除意见或改写正文');return}if(a==='approve'){approve();return}if(a==='confirmApprove'){if(!approvalTarget)return;const target=state.files.find(t=>t.id===approvalTarget.id);if(target.rev!==approvalTarget.rev||target.latest!==approvalTarget.rev||target.status!=='review'||needsScope(target)){$('#dialog').close();toast('版本或状态已变化，请重新检查');return}approvalTarget=null;$('#dialog').close();if(state.outcome==='failure'){target.notes.push('批准被拒绝（演示），本版本未批准。');render();toast('演示：质量结果已失效，请重新检查；未切换文件');return}if(state.outcome==='unknown'){target.status='unknown';render();return}advance(target);return}if(a==='reconcile'){advance(x);return}if(a==='reviewDraft'){const prior=earlierDraft(x);if(!prior)return;modal('核对上版草稿',`<p>草稿基于第 ${prior.rev} 版；当前查看第 ${x.rev} 版。</p><p class="draft-preview">${esc(prior.text)}</p><p>请先核对新版本中的内容和引用位置。带入后仍可编辑，不会自动提交；原草稿保留。</p>`,`<button class="primary" data-action="reuseDraft">已核对，带入当前意见框</button>`);return}if(a==='reuseDraft'){const prior=earlierDraft(x);if(!prior||x.rev!==x.latest)return;const current=x.drafts[x.rev]||'';x.drafts[x.rev]=current?`${current}\n\n${prior.text}`:prior.text;x.carriedDrafts=x.carriedDrafts||{};x.carriedDrafts[prior.rev]=prior.text;x.notes.push(`第 ${prior.rev} 版草稿经人工核对后带入第 ${x.rev} 版意见框，尚未提交（演示）。`);$('#dialog').close();state.reviewPane='feedback';render();$('#feedback').focus();return}if(a==='quote'){x.drafts[x.rev]=(x.drafts[x.rev]||'')+`关于 ${x.name} 第 ${x.rev} 版 · ${window.procurementFixtures[x.id].position}：`;render();$('#feedback').focus();return}if(a==='submit'){const text=x.drafts[x.rev]?.trim();if(!text||x.status!=='review')return;if(x.rev!==x.latest){toast('演示：提交目标已有新版本，旧意见已保留，请检查新版本后再提交');return}x.submitted={rev:x.rev,text};x.notes.push(`第 ${x.rev} 版修改意见已提交：${text}`);x.drafts[x.rev]='';x.status='running';x.notes.push('已请求处理并进入修改中（演示），无需再次启动。');render();toast('已提交并开始模拟修改，可继续写下轮草稿');return}if(a==='incoming'){if(x.latest>x.rev){toast('已有新版本提示');return}x.latest=x.rev+1;if(x.status==='approved')x.status='review';x.updates[x.latest]=x.submitted?.text||'此前已提交的要求（合成演示）';x.notes.push(`收到第 ${x.latest} 版；保留正在查看的第 ${x.rev} 版。`);render();return}if(a==='switch'){x.rev=x.latest;x.status='review';state.tab='changes';render();toast('已切换；旧版本草稿仍保留，未自动迁移');return}if(a==='old'){x.rev=x.id==='application'?2:3;state.tab='changes';render();return}if(a==='start'){if(x.status!=='submitted')return;x.status='running';x.notes.push('本文件开始修改（演示），范围未扩大。');render();return}if(a==='returned'){if(x.status!=='running')return;x.latest=Math.max(x.latest,x.rev)+1;x.updates[x.latest]=x.submitted?.text||'本轮修改要求';x.status='review';x.notes.push(`第 ${x.latest} 版交回（演示），待检查。`);render();return}if(a==='impact'){if(!['submitted','running'].includes(x.status))return;modal('建议同时修改关联文件',`<p>服务器执行 Agent 提出（演示）：本次引用编号核对可能涉及 <strong>采购申请单 · 第 ${state.files[2].latest} 版</strong>，建议核对编制说明中的合格供方名录编号 QR-GL-7.4.01-01。</p><p>影响依据：采购程序 §7 与采购申请单编制说明第 5 条共同引用合格供方名录；是否需要修改仍待核对。范围外的表格尚未修改。</p><p class="small muted">业务服务应校验建议及授权；本原型只演示确认交互。</p>`,`<button data-action="declineImpact">保持单文件范围</button><button class="primary" data-action="acceptImpact">确认扩大修改范围</button>`);return}if(a==='acceptImpact'||a==='declineImpact'){x.notes.push(a==='acceptImpact'?'已确认关联修改建议（演示）；采购申请单进入关联任务安排，尚未改写原版本。':'保留当前文件范围，关联修改建议未接受（演示）。');$('#dialog').close();render();toast(a==='acceptImpact'?'关联范围已确认（演示），等待后续任务安排':'未扩大修改范围');return}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.reviewPane){state.reviewPane=b.dataset.reviewPane;render();return}if(b.dataset.action==='changeDirectory'){changeDirectory();return}if(b.dataset.changeIndex!==undefined){$('#dialog').close();const current=f().changePositions?.[f().rev]||0;moveChange(Number(b.dataset.changeIndex)-current);return}if(b.dataset.changeStep){moveChange(Number(b.dataset.changeStep));return}if(b.dataset.quote){quoteLocation(b.dataset.quote);return}if(b.dataset.file)goFile(b.dataset.file);if(b.dataset.tab){state.tab=b.dataset.tab;render()}if(b.dataset.action)action(b.dataset.action);if(b.dataset.task){if(b.dataset.task==='initial-analysis'){state.scroll=window.scrollY;save();initialAnalysisEnter()}else if(b.dataset.task==='execution'){state.scroll=window.scrollY;save();location.hash='execution'}else if(b.dataset.task==='analysis'){state.scroll=window.scrollY;save();location.hash='analysis'}else if(b.dataset.task==='procurement'){state.scroll=window.scrollY;save();location.hash='work'}else if(b.dataset.task==='equipment'){state.scroll=window.scrollY;save();location.hash='supplement'}else modal('此场景尚未展开','<p>本轮原型重点验证采购成果的逐文件检查。其他卡片用于展示跨项目进度。</p>','<button class="primary" data-action="openWork">体验采购成果检查</button>')}if(b.dataset.action==='openWork'){$('#dialog').close();location.hash='work'}});
document.addEventListener('input',e=>{if(e.target.id==='changeSearch'){const query=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-search]').forEach(b=>{b.hidden=!b.dataset.search.toLowerCase().includes(query);if(!b.hidden)count++});$('#directoryResult').textContent=count?`找到 ${count} 处`:'未找到匹配位置';return}if(e.target.id==='feedback'){const x=f();x.drafts[x.rev]=e.target.value;save();document.querySelector('[data-action="submit"]').disabled=!e.target.value.trim()||x.status!=='review'||x.rev!==x.latest;$('#draftSaveState').textContent=e.target.value?'已保存个人草稿（模拟）':'个人草稿 · 仅本人可见（模拟）'}});
document.addEventListener('change',e=>{if(e.target.id==='contentPosition'){const section=document.getElementById(e.target.value);if(section){section.setAttribute('tabindex','-1');section.focus();section.scrollIntoView({block:'start'})}}if(e.target.id==='filter'){state.filter=e.target.value;render()}if(e.target.id==='viewVersion'){f().rev=Number(e.target.value);state.tab='changes';render()}if(e.target.id==='outcome'){state.outcome=e.target.value;save()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,location.hash==='#work'?0:state.scroll)});render();if(location.hash!=='#work')window.scrollTo(0,state.scroll);

// Keep tab navigation usable with a keyboard after each view redraw.
document.addEventListener('keydown',e=>{if(e.target.getAttribute('role')!=='tab'||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=['changes','full','sources','context'];let n=ids.indexOf(state.tab);n=e.key==='Home'?0:e.key==='End'?3:(n+(e.key==='ArrowRight'?1:3))%4;state.tab=ids[n];render();document.querySelector(`[data-tab="${state.tab}"][role="tab"]`).focus()});
